static IEnumerator WaitForMartaDonorPose(FcoDonorRig source, FcoDonorRig candidate,
    AnimationClip clip, float time, bool laying)
{
    source.BeginPose(clip, time, laying);
    candidate.BeginPose(clip, time, laying);
    float target = laying ? 0f : 1f;
    float deadline = Time.realtimeSinceStartup + 1.5f;
    // Let the production LateUpdate apply the sampled pose at least once.
    do
    {
        yield return null;
        if (Mathf.Abs(source.Bones.HeelPoseWeight - target) <= .001f &&
            Mathf.Abs(candidate.Bones.HeelPoseWeight - target) <= .001f)
            yield break;
    } while (Time.realtimeSinceStartup < deadline);

    throw new InvalidOperationException("Actual heel pose did not settle in PlayMode");
}

