static JArray M2DonorGraphics(FcoDonorRig rig,string directory,string stamp,string kind,string id){var images=new JArray();foreach(bool back in new[]{false,true}){string key="m2-"+Key(id).Substring(0,8)+"-"+stamp+"-"+kind+"-"+(back?"back":"front");RenderWardrobe(rig.Body,key,back);string path=directory+"/"+kind+"-"+(back?"back":"front")+".png";File.Copy(OutputRoot+"/review/"+key+".png",path,false);images.Add(new JObject{["scope"]="whole standing authored model",["png"]=path,["sha256"]=FinalFileSHA(path)});}var baked=FcoDonorCapture(rig.Skin);try{int[] all;if(id=="clothing.outfit_reiko"){var cache=JObject.Parse(File.ReadAllText(PreparedRoot+"/preparation.json"));var native=AssetDatabase.LoadAssetAtPath<GameObject>((string)cache[id]["source"]);var materials=native.GetComponentInChildren<SkinnedMeshRenderer>(true).sharedMaterials;var slots=Enumerable.Range(0,materials.Length).Where(i=>AssetDatabase.GetAssetPath(materials[i])=="Assets/ImportedActors/Wear/ReikoOutfit/Materials/Shoes.mat").ToArray();if(slots.Length!=1||rig.Skin.sharedMaterials.Length!=materials.Length||baked.subMeshCount!=materials.Length)throw new InvalidOperationException("Reiko source/derived Shoes slot correspondence changed");all=baked.GetTriangles(slots[0]);}else all=baked.triangles;var world=baked.vertices;foreach(bool left in new[]{false,true}){var points=all.Distinct().Select(i=>world[i]).Where(p=>left?rig.Body.transform.InverseTransformPoint(p).x<0:rig.Body.transform.InverseTransformPoint(p).x>0).ToArray();if(points.Length==0)throw new InvalidOperationException("Missing evidenced left/right detail region");var bounds=VertexBounds(points);var look=bounds.center;float size;if(id=="clothing.gloves_stars")size=Mathf.Max(.14f,bounds.size.magnitude*.6f);else{look.y=bounds.max.y-.025f;size=.16f;}foreach(bool back in new[]{false,true}){string path=directory+"/"+kind+"-"+(left?"left":"right")+"-"+(id=="clothing.gloves_stars"?"wrist-hand":"boot-cuff")+"-"+(back?"back":"front")+".png";M2RenderDetail(rig.Body,look,size,back,path);images.Add(new JObject{["scope"]=id=="clothing.gloves_stars"?"wrist and hand source region":"Reiko Shoes material only determines camera; whole model still rendered",["left"]=left,["back"]=back,["look"]=new JArray(look.x,look.y,look.z),["orthographicSize"]=size,["png"]=path,["sha256"]=FinalFileSHA(path)});}}}finally{Object.DestroyImmediate(baked);}return images;}
static void M2RenderDetail(GameObject body,Vector3 look,float size,bool back,string path){var preview=new PreviewRenderUtility();var meshes=new List<Mesh>();bool async=ShaderUtil.allowAsyncCompilation;ShaderUtil.allowAsyncCompilation=false;try{var parts=new List<(Mesh mesh,Matrix4x4 matrix,Material[] mats,MaterialPropertyBlock[] blocks)>();foreach(var r in body.GetComponentsInChildren<SkinnedMeshRenderer>(true)){if(!r.enabled||!r.gameObject.activeInHierarchy)continue;var mesh=new Mesh();meshes.Add(mesh);r.BakeMesh(mesh,true);var mats=r.sharedMaterials;var blocks=new MaterialPropertyBlock[mats.Length];for(int i=0;i<mats.Length;i++){blocks[i]=new MaterialPropertyBlock();r.GetPropertyBlock(blocks[i],i);if(blocks[i].isEmpty)r.GetPropertyBlock(blocks[i]);}parts.Add((mesh,r.transform.localToWorldMatrix,mats,blocks));}var camera=preview.camera;camera.orthographic=true;camera.orthographicSize=size;camera.transform.position=look+new Vector3(back?-.03f:.03f,.025f,back?-2:2);camera.transform.LookAt(look);camera.nearClipPlane=.01f;camera.farClipPlane=10;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.13f,.15f,.17f);preview.lights[0].intensity=1.15f;preview.lights[0].transform.rotation=Quaternion.Euler(35,back?0:180,0);preview.lights[1].intensity=.55f;preview.lights[1].transform.rotation=Quaternion.Euler(-15,back?160:-30,0);for(int pass=0;pass<2;pass++){preview.BeginStaticPreview(new Rect(0,0,768,768));foreach(var p in parts)for(int sm=0;sm<p.mesh.subMeshCount;sm++){int slot=Mathf.Min(sm,p.mats.Length-1);preview.DrawMesh(p.mesh,p.matrix,p.mats[slot],sm,p.blocks[slot]);}camera.Render();var image=preview.EndStaticPreview();if(pass==1)File.WriteAllBytes(path,image.EncodeToPNG());Object.DestroyImmediate(image);}}finally{foreach(var m in meshes)Object.DestroyImmediate(m);preview.Cleanup();ShaderUtil.allowAsyncCompilation=async;}}
